import { pathToFileURL } from 'node:url';
import {bottossonSamples} from '/home/lloydk/work/gma-benchmark/tests/helpers/bottosson-samples.js';
const methods=[['clip','clip'],['css-minde','cssMinde'],['oklch-cubic','oklchCubic'],['oklch-cubic-no-cache','oklchCubicNoCache'],['oklch-cubic-direct','oklchCubicDirect'],['oklch-halley','oklchHalley'],['oklch-ostrowski','oklchOstrowski'],['dualray','dualray'],['bottosson-lightness','bottossonLightness'],['bottosson-lightness','bottossonLightnessCached'],['edge-seeker/index','edgeSeeker'],['edge-seeker/index','edgeSeekerIndexed'],['raytrace','raytrace']];
const roots=['/tmp/gma-m4-bottosson-baseline','/home/lloydk/work/gma-benchmark'];
const samples=bottossonSamples('display-p3');
